    if (abs(oS - ownerF) > 0.5 && tS < 0.5) ownerEdge += 1.0;
    if (abs(oE - ownerF) > 0.5 && tE < 0.5) ownerEdge += 1.0;
    if (abs(oW - ownerF) > 0.5 && tW < 0.5) ownerEdge += 1.0;
